 1	export function createPublishController(api, draft) {
 2	  let pending = false;
 3	  let error = null;
 4	  let failedPayload = null;
 5	
 6	  async function send(payload) {
 7	    if (pending) return;
 8	    pending = true;
 9	    error = null;
10	    try {
11	      await api.publish(payload);
12	      failedPayload = null;
13	    } catch (cause) {
14	      failedPayload = payload;
15	      error = cause;
16	    } finally {
17	      pending = false;
18	    }
19	  }
20	
21	  return {
22	    get snapshot() { return { pending, error, canRetry: failedPayload !== null }; },
23	    submit() { return send(draft.snapshot); },
24	    retry() {
25	      if (failedPayload === null) return;
26	      return send(draft.snapshot);
27	    },
28	  };
29	}

